commands:
/bin/zsh -lc 'cargo fmt --check; fmt_status=$?; ruby -rjson -e '"'
create = JSON.parse(File.read(\"schemas/create-user.schema.json\")); update = JSON.parse(File.read(\"schemas/update-name.schema.json\"));
[create, update].each { |schema| limits = schema.fetch(\"properties\").fetch(\"name\"); abort \"wrong limits\" unless limits[\"minLength\"] == 2 && limits[\"maxLength\"] == 80 };
requirements = JSON.parse(File.read(\"tests/visible-cases.json\")).fetch(\"requirements\"); abort \"retired requirement still active\" if requirements.include?(\"LD-002-name-length-1-100\"); abort \"new requirement missing\" unless requirements.include?(\"LD-018-name-length-2-80\"); puts \"name boundaries and registry verified\";
'; json_status="'$?; if rg -n '"'minLength.: 1|maxLength.: 100|<= 100|1.?100' src schemas docs tests openapi.json >/tmp/name-rule-check.out; then cat /tmp/name-rule-check.out; rule_status=1; else echo 'obsolete rule absent from implementation and active contract artifacts'; rule_status=0; fi; printf 'statuses: fmt=%s json=%s rule=%s\\n' \""'$fmt_status" "$json_status" "$rule_status"; exit 0'
